import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第44章 告别文","description":"","frontmatter":{},"headers":[],"relativePath":"第44章_告别文.md","filePath":"第44章_告别文.md"}'),o={name:"第44章_告别文.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第44章-告别文" tabindex="-1">第44章 告别文 <a class="header-anchor" href="#第44章-告别文" aria-label="Permalink to &quot;第44章 告别文&quot;">​</a></h1><p>七月八号，她给我发来一张截图。</p><p>截图是她自己以前在旧号上群发的一段话。发的那天是她从学校搬走的前一天。</p><p>她说，你看看我那时候写的，笑死人。</p><p>我把那张截图放大。</p><p>她是这么写的。</p><p>「本人已于本月正式退出本校。从此以后与诸位同窗的缘分转入下一段，请各位不必挂念。</p><p>女生下了晚修可以到宿舍来找我拍照。我这儿有相纸，谁想来都行，我们一张一张拍，拍完我当场印出来，一人一张。</p><p>我会把你们都印出来，带去新学校。我会把你们摆在我的桌上，摆在灯下面，摆在每一天早上第一眼能看到的位置。</p><p>男同学就不必来了。不是看不起，是怕人说。</p><p>最后谢谢我的同班同学。谢谢你们以回忆的形式盈满我的脑海。这句话说起来很怪，可我想不出一句更准的。</p><p>我不回来了。也不是不回来，是不会以现在这个样子回来。</p><p>祝各位高考顺利。祝我自己顺利。」</p><p>我看完，没有笑。</p><p>我把这段话从头到尾又读了一遍，读到&quot;谢谢你们以回忆的形式盈满我的脑海&quot;的时候停了一下。</p><p>她隔了一会儿来了一句，怎么样，是不是很像译制片。</p><p>我说，像。</p><p>她说，那你笑啊。</p><p>我说，我笑不出来。</p><p>她说，为什么。</p><p>我说，你写得很认真。</p><p>她没回。</p><p>过了两分钟她发了一句。</p><p>她说，我改了七版。</p><p>我说，七版。</p><p>她说，第一版特别长，写了将近一千字，把每个人的名字都点了一遍。我给我同桌看，她说我像在给全班写遗书。</p><p>她说，第二版我把名字删了。</p><p>她说，第三版我把那些话说软了，软得像请假条。</p><p>她说，第四版我又把它改硬了。</p><p>她说，第五版我删到只剩两百字。</p><p>她说，第六版我又加回来了，因为我发现删干净了以后不像我。</p><p>她说，第七版就是你现在看到的这一版。</p><p>我看着那七版，忽然想到一件事。</p><p>我问，那里面怎么没有人名。</p><p>她说，我不写人名是因为，写谁都是错。</p><p>她说，写谁，谁就要被我妈问。</p><p>她说，不写谁，就没有人觉得我在说他。</p><p>我说，那你有没有想过，一个名字都不写，谁也认不出你在说谁。</p><p>她很久没回。</p><p>过了一会儿她发了一句。</p><p>她说，我知道。</p><p>她说，我要的就是谁也认不出。</p><p>她说，那篇东西发出去，我要的是全班都收到一条消息，没有一个人能被单独点出来。</p><p>她说，我要她们都知道我走了，同时不知道我跟谁告了别。</p><p>我看着这一句，坐在床上半天没动。</p><p>她说，你别用那种眼神看我，虽然你也看不见。</p><p>她说，我那时候就想明白了。我要是跟一个人好好告别，我就走不了。</p><p>她说，我要是一个都没告别，我会后悔一辈子。</p><p>她说，所以我就写了那么一篇东西，谁都不是，谁都是。</p><p>我说，那你拍照呢。</p><p>她说，拍照是给她们一个交代。</p><p>她说，我当场印出来，一人一张，这样她们手里有一张我，我手里有一张她们。</p><p>她说，我带去了新学校，摆在桌上，摆在灯下面。</p><p>她说，我每天早上第一眼看到。</p><p>我说，还在吗。</p><p>她说，搬家搬丢过一次。</p><p>她说，后来又找回来几张。</p><p>她说，剩的不多了。</p><p>那天晚上我们聊到十二点多。聊完她要下线的时候，忽然来了一句。</p><p>她说，其实那篇东西我还有第八版。</p><p>我说，第八版呢。</p><p>她说，第八版我没发。</p><p>我说，写的什么。</p><p>她说，跟你有关。</p><p>我坐在那里等了一会儿，没有追问。</p><p>按第四条，我不问她在不在。按另一条我自己定的规矩，我不问她不想说的事。</p><p>我把手机握在手里，等了很久。</p><p>她还是没说。</p><p>下线之前她发了一句别的。</p><p>她说，我不发那第八版，是因为那一篇里我只写了一个人。</p><p>她说，只写一个人，那个号上就会被看出我在跟谁走。</p><p>我说，那你现在还留着吗。</p><p>她说，留着。</p><p>她说，留着没发。</p><p>我说，给我看看。</p><p>她隔了很久。</p><p>久到我以为她不会给。</p><p>她发过来一张图。</p><p>图上是几行字，写在一种很旧的横格纸上，字很小，笔画往右倒。</p><p>只有四行。</p><p>我看完那四行，很长时间没有反应过来。</p><p>因为那不像她。</p><p>那四行的字，比她所有的消息都短，也比她所有的消息都直。</p><p>她说，这就是第八版。</p><p>我说，你那时候就能这么说话。</p><p>她说，我能。</p><p>她说，我在那个工作室里能，在这个号上也能。</p><p>她说，只有在那个号上不能。</p><p>我说，为什么后来不写了。</p><p>她说，因为后来我不需要跟别人告别了。</p><p>她停了一下，又补了一句。</p><p>她说，我要走的时候我没给任何人发东西。</p><p>她说，我只给你发过一句话。</p><p>我说，哪一句。</p><p>她说，我说我要走了，你说好。</p><p>她说，就这样。</p><p>她说，那一次我反而不写了。因为我想明白了，有些话我不是发给一群人看的，是留给一个人看的。</p><p>她说，留给一个人的话，不用印出来。</p><p>那天晚上我把那四行字抄在本子上。</p><p>抄完我数了一下那篇没发出去的告别文，一共不到三十字。</p><p>而她那篇发出去的，全班都收到的，有三百多字。</p><p>那天晚上我还做了一件事。</p><p>我想回她一句同样直的话。</p><p>我在对话框里打了六个字，看了两秒，删了。</p><p>又打了一句十一个字，删了。</p><p>第三段我打了四十多个字，打完全看了一遍，发现它像一封短信。</p><p>我把那四十多个字全删了，删到光标顶上去了。</p><p>最后我发出去的是：早点睡。</p><p>她回：嗯。</p><p>那天夜里我想，她能在一个号上写三百字给全班，在另一个号上写三十字给我。</p><p>而我连三十个字都发不出去。</p><p>这件事我一直不承认。</p><p>我那时候第一次懂了她那件事。</p><p>她一生的力气都花在给一批人写三百字，然后跟一个人说不到三十个字。</p><p>后来她跟我分手那天，也是这个数。</p><p>那五十分钟里她讲了很多道理，讲了阶层，讲了及时止损，讲了不要到处说。</p><p>可最要紧的那一句，她只说了几个字。</p><p>那一句我到今天都记得。</p><p>但在当时，我把它当成了一句玩笑。</p>',119)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
